proxy.code:
# Nginx
location /t.js {
  proxy_pass https://stats.example.com/js/tkb_a1b2c3d4.js;
  proxy_ssl_server_name on;
}
location /api/e {
  proxy_pass https://stats.example.com/api/e;
  proxy_ssl_server_name on;
  proxy_set_header X-Trckable-Client-IP $remote_addr;
  proxy_set_header X-Trckable-Proxy-Key your-proxy-key;
}

<!-- every page, in <head>: the script and its events from your domain -->
<script
  defer
  data-site="tkb_a1b2c3d4"
  data-domain="example.com"
  src="/t.js">
</script>

crawlers.code:
// Next.js — middleware.ts
import { reportCrawler } from 'trckable/server'

export function middleware(req) {
  reportCrawler({
    host: 'https://stats.example.com',
    site: 'tkb_a1b2c3d4',
    key: process.env.TRCKABLE_PROXY_KEY,
    url: req.url,
    ua: req.headers.get('user-agent'),
  })
}
